def target_door_open(env):
    return any(c is not None and c.type == "door" and c.is_open for b in [max([y for x in range(env.width) for y in range(env.height) for cell in [env.grid.get(x, y)] if cell is not None and cell.type == "ball"], default=env.agent_pos[1]) // (env.room_size - 1)] for y in range((env.room_size - 1) * b, (env.room_size - 1) * b + env.room_size) for c in [env.grid.get(env.width - env.room_size, y)])
